module route_division (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [9:0] x_arr [0:7],\n    input [9:0] y_arr [0:7],\n    output reg [10:0] result,\n    output reg done\n);\n\n    // State encoding\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] LOAD_INPUTS = 4'd1;\n    localparam [3:0] INIT_VARS   = 4'd2;\n    localparam [3:0] LOOP_START  = 4'd3;\n    localparam [3:0] PROCESS_PAIR = 4'd4;\n    localparam [3:0] CHECK_J     = 4'd5;\n    localparam [3:0] INCR_I      = 4'd6;\n    localparam [3:0] UPDATE_MAX  = 4'd7;\n    localparam [3:0] CHECK_I     = 4'd8;\n    localparam [3:0] UPDATE_BEST = 4'd9;\n    localparam [3:0] INCR_PART   = 4'd10;\n    localparam [3:0] CHECK_DONE  = 4'd11;\n    localparam [3:0] DONE_STATE  = 4'd12;\n    \n    reg [3:0] current_state, next_state;\n    \n    // Internal registers\n    reg [3:0] N_reg;\n    reg [10:0] best_max;\n    reg [7:0] partition;\n    reg [2:0] i;\n    reg [2:0] j;\n    reg [10:0] max_A;\n    reg [10:0] max_B;\n    reg [7:0] max_partition;\n    \n    // Distance calculation\n    wire [9:0] x_i = x_arr[i];\n    wire [9:0] x_j = x_arr[j];\n    wire [9:0] y_i = y_arr[i];\n    wire [9:0] y_j = y_arr[j];\n    wire [9:0] dx = (x_i > x_j) ? (x_i - x_j) : (x_j - x_i);\n    wire [9:0] dy = (y_i > y_j) ? (y_i - y_j) : (y_j - y_i);\n    wire [10:0] dist = dx + dy;\n    \n    wire in_A_i = ~partition[i];\n    wire in_A_j = ~partition[j];\n    wire in_B_i = partition[i];\n    wire in_B_j = partition[j];\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= IDLE;\n            done <= 1'b0;\n            result <= 11'd0;\n            best_max <= 11'h7FF;\n            partition <= 8'd0;\n            i <= 3'd0;\n            j <= 3'd0;\n            max_A <= 11'd0;\n            max_B <= 11'd0;\n            N_reg <= 4'd0;\n            max_partition <= 8'd0;\n        end \n        else begin\n            current_state <= next_state;\n            \n            case (current_state)\n                LOAD_INPUTS: begin\n                    N_reg <= N;\n                    max_partition <= (1 << N) - 1;\n                end\n                \n                INIT_VARS: begin\n                    best_max <= 11'h7FF;\n                    partition <= 8'd0;\n                end\n                \n                LOOP_START: begin\n                    i <= 3'd0;\n                    j <= 3'd1;\n                    max_A <= 11'd0;\n                    max_B <= 11'd0;\n                end\n                \n                PROCESS_PAIR: begin\n                    if (in_A_i && in_A_j) begin\n                        max_A <= (dist > max_A) ? dist : max_A;\n                    end\n                    if (in_B_i && in_B_j) begin\n                        max_B <= (dist > max_B) ? dist : max_B;\n                    end\n                end\n                \n                CHECK_J: begin\n                    if (j < N_reg) j <= j + 3'd1;\n                end\n                \n                INCR_I: begin\n                    i <= i + 3'd1;\n                    j <= i + 3'd2;\n                end\n                \n                UPDATE_MAX: begin\n                    best_max <= (max_A > max_B) ? ((max_B > best_max) ? best_max : max_B)\n                                               : ((max_A > best_max) ? best_max : max_A);\n                end\n                \n                INCR_PART: begin\n                    partition <= partition + 8'd1;\n                end\n                \n                DONE_STATE: begin\n                    result <= best_max;\n                    done <= 1'b1;\n                end\n                \n                default: ;\n            endcase\n        end\n    end\n    \n    always @(*) begin\n        next_state = current_state;\n        case (current_state)\n            IDLE:        next_state = start ? LOAD_INPUTS : IDLE;\n            LOAD_INPUTS: next_state = INIT_VARS;\n            INIT_VARS:   next_state = LOOP_START;\n            LOOP_START:  next_state = (N_reg > 3'd2) ? PROCESS_PAIR : UPDATE_MAX;\n            \n            PROCESS_PAIR: next_state = CHECK_J;\n            \n            CHECK_J: begin\n                if (j < N_reg) next_state = PROCESS_PAIR;\n                else if (i < N_reg-2) next_state = INCR_I;\n                else next_state = UPDATE_MAX;\n            end\n            \n            INCR_I: next_state = PROCESS_PAIR;\n            \n            UPDATE_MAX: begin\n                if (partition < max_partition) next_state = INCR_PART;\n                else next_state = DONE_STATE;\n            end\n            \n            INCR_PART: next_state = LOOP_START;\n            \n            DONE_STATE: next_state = start ? DONE_STATE : IDLE;\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \nendmodule